@layer teum.base {
* { box-sizing: border-box; }

button,
input,
textarea,
select { font: inherit; }

button { color: inherit; }

button,
[role="option"] { -webkit-tap-highlight-color: transparent; }

::selection { color: var(--teum-on-inverse); background: var(--teum-inverse); }

:focus-visible { outline: var(--teum-focus-width) solid var(--teum-focus-control); outline-offset: var(--teum-focus-offset); }

.teum-sr-only,
.teum-sr-only:not(:focus):not(:active) {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

@media (prefers-reduced-motion: reduce) {
* { scroll-behavior: auto !important; }
}
}
